{
  "isPaired": (input: string): boolean => {
    const stack: string[] = [];
    const pairs: { [key: string]: string } = { '(': ')', '{': '}', '[': ']' };

    for (const char of input) {
      if (pairs[char]) {
        stack.push(char);
      } else if (stack.length === 0 || pairs[stack.pop()!] !== char) {
        return false;
      }
    }

    return stack.length === 0;
  }
}

